import axios from "axios";
import { useEffect, useRef, useState } from "react";
import { Link, useNavigate, useParams, useSearchParams } from "react-router-dom";
import { useCart } from "./CartContext";
import { timeAgo } from "../utils/timeAgo";
import "./review.css";
import {
  FaStar,
  FaUserMd,
  FaStethoscope,
  FaGraduationCap,
  FaCalendarAlt,FaInfoCircle
} from "react-icons/fa";
import UnifiedAuthModal from "./UnifiedAuthModal";

const ProductDetails = () => {
const [searchParams] = useSearchParams();

const { id } = useParams();
  
  const [service, setService] = useState(null);
  const [centreId, setCentreId] = useState(null);
  const [showDoctorModal, setShowDoctorModal] = useState(false);
  const [selectedDoctor, setSelectedDoctor] = useState(null);
  const [reviewData, setReviewData] = useState({ rating: 0, review: "" });
  const [submitting, setSubmitting] = useState(false);
  const [reviews, setReviews] = useState([]);
  const [loading, setLoading] = useState(true);
  const { activeTab } = useCart();
  const [openDay, setOpenDay] = useState(null);
  const [showLoginModal, setShowLoginModal] = useState(false);

  useEffect(() => {
    const fetchService = async () => {
      try {
        const response = await axios.get(
          `${process.env.REACT_APP_BACKEND_URL}/api/centreService/decrypted/${id}`
        );
        setService(response.data);
        setCentreId(response.data?.service?.centre?._id);
      } catch (error) {
        console.error("Error fetching service:", error);
      }
    };

    fetchService();
  }, [id]);

  const { addToCart } = useCart();

  const navigate = useNavigate();

  const handleBookNow = async (serviceId, fromPage) => {
    try {
      const response = await axios.get(
        `${process.env.REACT_APP_BACKEND_URL}/api/centreService/decrypted/${serviceId}`
      );
      const selectedService = response.data;
      addToCart(selectedService); // from context
      navigate("/cart", { state: { from: fromPage } });
    } catch (error) {
      console.error("Error adding to cart", error);
    }
  };

  const handleDoctorClick = (doctor) => {
    setSelectedDoctor(doctor);
    setShowDoctorModal(true);
  };

  const closeDoctorModal = () => {
    setShowDoctorModal(false);
    setSelectedDoctor(null);
  };
  useEffect(() => {
    const savedDraft = JSON.parse(localStorage.getItem("pendingReview"));
    if (savedDraft && savedDraft.serviceId === id) {
      setReviewData(savedDraft.data);
    } else {
      // Clear old draft if it belongs to another service
      localStorage.removeItem("pendingReview");
    }
  }, [id]);

  const handleRatingClick = (rating) => {
    setReviewData((prev) => ({ ...prev, rating }));
  };

  const handleReviewSubmit = async (e) => {
    e.preventDefault();

    if (
      (!reviewData.rating || reviewData.rating <= 0) &&
      !reviewData.review.trim()
    ) {
      alert("Please provide rating or review");
      return;
    }

    const userId = localStorage.getItem("userId");

    if (!userId) {
      localStorage.setItem(
        "pendingReview",
        JSON.stringify({
          serviceId: id,
          data: reviewData,
        })
      );
      setShowLoginModal(true);
      return;
    }

    setSubmitting(true);
    try {
      // ✅ FIXED: Prepare data properly - only send what user provided
      const payload = {
        userId,
        serviceId: id,        ...(reviewData.rating > 0 && { rating: reviewData.rating }),
        ...(reviewData.review.trim() && { review: reviewData.review.trim() }),
      };
      await axios.post(
        `${process.env.REACT_APP_BACKEND_URL}/api/review`,
        payload
      );
      alert("Review submitted successfully!");
      setReviewData({ rating: 0, review: "",type:"service"});
      localStorage.removeItem("pendingReview");
    } catch (error) {
      console.error("Error submitting review:", error);
      // alert("Failed to submit review. Please try again.");
      alert(
        error?.response?.data?.message ||
          "Failed to submit review. Please try again."
      );
      // setReviewData({ rating: 0, review: "" });
    } finally {
      setSubmitting(false);
    }
  };

  const modalRef = useRef(null);
  const viewModalRef = useRef(null);

  useEffect(() => {
    // Handle click outside
    const handleClickOutside = (event) => {
      if (
        modalRef.current &&
        !modalRef.current.contains(event.target) &&
        showDoctorModal
      ) {
        showDoctorModal(false);
      }
    };

    document.addEventListener("mousedown", handleClickOutside);
    if (showDoctorModal) {
      document.body.style.overflow = "hidden"; // Disable background scroll
    } else {
      document.body.style.overflow = "auto"; // Enable background scroll
    }

    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
      document.body.style.overflow = "auto"; // Cleanup when component unmounts
    };
  }, [showDoctorModal]);

  useEffect(() => {
    const fetchReviews = async () => {
      try {
        const res = await axios.get(
          `${process.env.REACT_APP_BACKEND_URL}/api/review/service/${id}`
        );
        setReviews(res.data.reviews || []);
      } catch (err) {
        console.error("Error fetching reviews:", err);
      } finally {
        setLoading(false);
      }
    };

    fetchReviews();
  }, [id]);

        const createSlug = (text) => {
  if (!text) return '';
  return text
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-') 
    .replace(/^_|_$/g, ''); 
};
     

  if (loading) return <p>Loading reviews...</p>;

  return (
    <>
     
    <div className="product-details mt-32 padding-b-120">
      <div className="container container-two">
        <div className="row gy-4">
          <div className="col-lg-8">
            <div className="tab-content" id="pills-tabContent">
              <div
                // className="tab-pane fade show active"
                className={`tab-pane fade ${
                  activeTab === "details" ? "show active" : ""
                }`}
                id="pills-product-details"
                role="tabpanel"
                aria-labelledby="pills-product-details-tab"
                tabIndex={0}
              >
                {/* Product Details Content Start */}
                <div className="product-details">
                  <div className="product-details__thumb"></div>

                  <p className="product-details__desc">
                    {service?.service?.description}
                  </p>

                  <div>
                    <ul>
                      <li className=""  style={{ display: "flex", gap: "10px", alignItems: "center" }}>
                        <span className="name">Category:</span>
                        <span className="details" style={{ marginLeft: "0px" }}>
                          {service?.service?.serviceCategory}
                        </span>
                      </li>
                    </ul>
                  </div>


                  <div className="product-details__item mt-4">
                    <h2 className="product-details__title mb-3 ">Facilities</h2>

                    {service?.service?.centre?.availableFacilities?.length >
                    0 ? (
                      <ul
                        className="product-list"
                        style={{
                          display: "grid",
                          gridTemplateColumns: "1fr 1fr", // 2 columns
                          gap: "0px 20px",
                          paddingLeft: "17px",
                          margin: 0,
                        }}
                      >
                        {service.service.centre.availableFacilities.map(
                          (facility, index) => (
                            <li
                              className="product-list__item"
                              key={index}
                              style={{ margin: "3px 0" }} // reduce vertical gap between items
                            >
                              {facility}
                            </li>
                          )
                        )}
                      </ul>
                    ) : (
                      <p>Facilities Not Mentioned</p>
                    )}
                  </div>

                  <div className="product-details__item">
                    <h2 className="product-details__title mb-3">
                      Insurance Availability
                    </h2>
                    {service?.service?.centre?.availableInsurance.length > 1 ? (
                      <ul
                        className="product-list"
                        style={{
                          display: "grid",
                          gridTemplateColumns: "1fr 1fr", // 2 columns
                          gap: "0px 20px",
                          paddingLeft: "17px",
                          margin: 0,
                        }}
                      >
                        {service?.service?.centre?.availableInsurance?.map(
                          (insurance, index) => (
                            <li
                              className="product-list__item"
                              key={index}
                              style={{
                                margin: "3px 0", // <-- reduce vertical gap between items
                              }}
                            >
                              {insurance}
                            </li>
                          )
                        )}
                      </ul>
                    ) : (
                      <p>No Insurance Available</p>
                    )}
                  </div>
                </div>

                {/* Review Form Start */}
                {/* <div className="review-form mt-5  d-none d-lg-block">
                  <h5>Write a Review</h5>
                  <form onSubmit={handleReviewSubmit}>
                    <div className="mb-3">
                      <label className="fw-bold">Rating</label>
                      <div className="stars">
                        {[1, 2, 3, 4, 5].map((star) => {
                          const fillValue = reviewData.rating;
                          return (
                            <span
                              key={star}
                              className={`star ${
                                star <= fillValue ? "filled" : ""
                              }`}
                              onClick={() => handleRatingClick(star)}
                            >
                              ★
                            </span>
                          );
                        })}
                      </div>
                      <small className="text-muted">
                        Click to rate (1-5 stars)
                      </small>
                    </div>

                    <div className="mb-3">
                      <label className="fw-bold">Your Review</label>
                      <textarea
                        placeholder="Share your experience with this service..."
                        value={reviewData.review}
                        onChange={(e) =>
                          setReviewData((prev) => ({
                            ...prev,
                            review: e.target.value,
                          }))
                        }
                        rows="4"
                        maxLength="1000"
                        // required
                      />
                      <small>{reviewData.review.length}/1000 characters</small>
                    </div>

                    <button
                      type="submit"
                      className="submit-btn"
                      disabled={
                        submitting ||
                        (!reviewData.rating && !reviewData.review.trim())
                      }
                      // disabled={
                      //   submitting ||
                      //   !reviewData.rating ||
                      //   !reviewData.review.trim()
                      // }
                    >
                      {submitting ? "Submitting..." : "Submit Review"}
                    </button>
                  </form>
                </div> */}

                <div className="review-section d-none d-lg-block">
  <div className="review-card">
    <h5 className="review-title">Write a Review</h5>

    <form onSubmit={handleReviewSubmit}>
      {/* Rating */}
      <div className="review-group">
        <label>
          Rating <span>(Optional)</span>
        </label>

        <div className="review-stars">
          {[1, 2, 3, 4, 5].map((star) => (
            <span
              key={star}
              className={`review-star ${
                star <= reviewData.rating ? "filled" : ""
              }`}
              onClick={() => handleRatingClick(star)}
            >
              ★
            </span>
          ))}
        </div>

        <small>Click to rate (1–5 stars) – Optional</small>
      </div>

      {/* Review Text */}
      <div className="review-group">
        <label>Your Review</label>

        <textarea
          placeholder="Share your experience with this service..."
          value={reviewData.review}
          onChange={(e) =>
            setReviewData((prev) => ({
              ...prev,
              review: e.target.value,
            }))
          }
          rows="4"
          maxLength="1000"
        />

        <small>{reviewData.review.length}/1000 characters</small>
      </div>

      <button
        type="submit"
        className="review-submit"
        disabled={
          submitting ||
          (!reviewData.rating && !reviewData.review.trim())
        }
      >
        {submitting ? "Submitting..." : "Submit Review"}
      </button>
    </form>
  </div>
</div>

                {/* Review Form End */}

                {/* Product Details Content End */}
              </div>

              <div
                // className="tab-pane fade "
                className={`tab-pane fade ${
                  activeTab === "ratings" ? "show active" : ""
                }`}
                id="pills-rating"
                role="tabpanel"
                aria-labelledby="pills-rating-tab"
                tabIndex={0}
              >
                <div className="product-review-wrapper">
                  {loading ? (
                    <p>Loading reviews...</p>
                  ) : reviews.length > 0 ? (
                    reviews.map((review) => (
                      <div className="product-review" key={review._id}>
                        <div className="product-review__top flx-between">
                          {/* ⭐ Rating */}
                          <div className="product-review__rating flx-align">
                            <div className="d-flex align-items-center gap-1">
                              <ul className="star-rating">
                                {[1, 2, 3, 4, 5].map((star) => (
                                  <li
                                    key={star}
                                    className="star-rating__item font-11"
                                    style={{
                                      color:
                                        star <= review.rating
                                          ? "#ffc107"
                                          : "#ddd",
                                    }}
                                  >
                                  <FaStar />
                                  </li>
                                ))}
                              </ul>
                              <span className="star-rating__text text-body">
                                {typeof review.rating === "number"
                                  ? review.rating.toFixed(1)
                                  : "0.0"}
                                {/* {typeof review.rating === "number" ? review.rating.toFixed(1) : "0.0"} */}
                              </span>
                            </div>
                          </div>

                          {/* 👤 Reviewer name + time */}
                          <div className="product-review__date">
                            by{" "}
                            <span className="product-review__user text-primary">
                              {review.userName}
                            </span>{" "}
                            {timeAgo(review.updatedAt)}
                          </div>
                        </div>

                        {/* 📝 Review text */}
                        <div className="product-review__body">
                          <p className="product-review__desc">
                            {review.review}
                          </p>
                        </div>
                      </div>
                    ))
                  ) : (
                    <p className="text-muted">
                      No reviews found for this service.
                    </p>
                  )}
                </div>
              </div>

              <div
                className="tab-pane fade"
                id="pills-comments"
                role="tabpanel"
                aria-labelledby="pills-comments-tab"
                tabIndex={0}
              >
              </div>
            </div>
          </div>

          {/* ======================= Product Sidebar Start ========================= */}
          {activeTab !== "ratings" && (
            <div className="col-lg-4">
              <div className="product-sidebar section-bg">
                <div className="product-sidebar__top position-relative flx-between gap-1">
                  <button type="button" className="font-heading font-18">
                    Book Appointment
                  </button>

                  <div className="flx-align gap-2">
                    <h6 className="product-item__price text-success mb-0">
                      ₹{service?.service?.totalPrice}
                    </h6>
                    {service?.service?.discountPrice ? (
                      <span className="product-item__prevPrice text-decoration-line-through">
                        ₹{service?.service?.actualPrice}
                      </span>
                    ) : null}
                  </div>
                </div>
                <Link
                  to="/cart"
          state={{ from: `/service/${service?.service?.serviceSlug}/${id}` }}
                  className="btn btn-main d-flex w-100 justify-content-center align-items-center gap-2 pill px-sm-5 mt-32"
                  onClick={() =>
                    handleBookNow(
                      id,
                      `/service/${service?.service?.serviceSlug}/${id}`
                    )
                  }
                >
                  <img src="/assets/images/icons/add-to-cart.svg" alt=""  loading="lazy"/>
                  Book Now
                </Link>
                {/* Author Details Start*/}
                <div className="author-details-refined mt-4">
                  <style jsx>{`
                    .doctor-card-elevated {
                      background: #ffffff;
                      border: 1px solid #eef2f6;
                      border-radius: 16px;
                      padding: 16px;
                      transition: all 0.3s ease;
                      box-shadow: 0 4px 12px rgba(226, 232, 240, 0.4);
                    }
                    .doctor-card-elevated:hover {
                      transform: translateY(-2px);
                      box-shadow: 0 8px 24px rgba(226, 232, 240, 0.6);
                      border-color: #d1d9e2;
                    }
                    .doctor-image-wrapper {
                      width: 70px;
                      height: 70px;
                      border-radius: 50%;
                      overflow: hidden;
                      border: 2px solid #fff;
                      box-shadow: 0 0 0 1px #e2e8f0;
                    }
                    .doctor-name-btn {
                      color: #1a202c !important;
                      font-weight: 700 !important;
                      transition: color 0.2s;
                      text-align: left;
                    }
                    .doctor-name-btn:hover {
                      color: #2563eb !important;
                    }
                    .doctor-specialty {
                      font-size: 13px;
                      color: #64748b;
                      font-weight: 500;
                      text-transform: uppercase;
                      letter-spacing: 0.5px;
                      margin-bottom: 2px;
                    }
                    .doctor-qualification {
                      font-size: 14px;
                      color: #475569;
                      margin-bottom: 8px;
                    }
                    .view-profile-btn {
                      font-size: 13px;
                      font-weight: 600;
                      color: #2563eb;
                      padding: 0;
                      background: transparent;
                      border: none;
                      text-decoration: none;
                      display: inline-flex;
                      align-items: center;
                      gap: 4px;
                      transition: gap 0.2s;
                    }
                    .view-profile-btn:hover {
                      gap: 6px;
                      text-decoration: underline;
                    }
                  `}</style>
                  
                  {service?.service?.doctors?.map((doctor, index) => (
                    <div
                      key={doctor._id || index}
                      className="doctor-card-elevated d-flex align-items-center gap-3 mb-3"
                    >
                      <div className="doctor-image-wrapper flex-shrink-0">
                        <img
                          src={doctor.profilePhoto}
                          alt={doctor.name}
                          style={{
                            width: "100%",
                            height: "100%",
                            objectFit: "cover",
                            cursor: "pointer",
                          }}
                          onClick={() => handleDoctorClick(doctor)}
                        />
                      </div>

                      <div className="author-details__content flex-grow-1">
                        <div className="doctor-specialty">
                          {doctor.specialization}
                        </div>
                        <h6 className="mb-1">
                          <button
                            className="p-0 border-0 bg-transparent doctor-name-btn font-18"
                            onClick={() => handleDoctorClick(doctor)}
                          >
                            {doctor.name}
                          </button>
                        </h6>
                        <div className="doctor-qualification">
                          {doctor.qualification}
                        </div>
                        <button
                          className="view-profile-btn"
                          onClick={() => handleDoctorClick(doctor)}
                        >
                          View Profile <span className="arrow">→</span>
                        </button>
                      </div>
                    </div>
                  ))}
                </div>
                {/* Author Details End */}
                {/* Meta Attribute List Start */}
                <ul className="meta-attribute">
                  <li className="meta-attribute__item d-block">
                    <span className="name mb-2 d-block" style={{width: "100%", fontWeight: "600"}}>Availability Time</span>
                    <div className="details w-100">
                      {(() => {
                        const groupedSlots = service?.service?.slots?.reduce((acc, slot) => {
                          if (!acc[slot.day]) acc[slot.day] = [];
                          acc[slot.day].push(slot);
                          return acc;
                        }, {}) || {};

                        const daysOrder = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];
                        const sortedDays = Object.keys(groupedSlots).sort((a, b) => 
                          daysOrder.indexOf(a) - daysOrder.indexOf(b)
                        );

                        if (sortedDays.length === 0) return <p className="text-muted small">No slots available</p>;

                        return sortedDays.map((day) => (
                          <div key={day} className="mb-1 border-bottom border-gray-light">
                            <button
                              type="button"
                              onClick={() => setOpenDay(openDay === day ? null : day)}
                              className="w-100 text-start d-flex justify-content-between align-items-center py-2 bg-transparent border-0 px-0"
                              style={{ 
                                fontWeight: "600", 
                                fontSize: "14px",
                                color: openDay === day ? "var(--primary-color, #0d6efd)" : "inherit" 
                              }}
                            >
                              <span>{day}</span>
                              <span style={{ 
                                transition: "transform 0.3s ease",
                                transform: openDay === day ? "rotate(180deg)" : "rotate(0)",
                                fontSize: "10px"
                              }}>▼</span>
                            </button>
                            {openDay === day && (
                              <div className="pb-2">
                                {groupedSlots[day].map((slot) => (
                                  <div key={slot._id} className="small text-muted mb-1 ps-2 border-start border-primary border-2">
                                    {slot.from} - {slot.to}
                                  </div>
                                ))}
                              </div>
                            )}
                          </div>
                        ));
                      })()}
                    </div>
                  </li>
                </ul>
                {/* Meta Attribute List End */}
                {/* <div className="author-details__content"> */}
                <span className="name" style={{ color: "black" }}>
                  Doctor Report Uploading Time:
                </span>{" "}
                <span className="name"> {service?.service?.reportTiming}</span>
                {/* </div> */}
                <div
                  style={{
                    marginTop: "20px",
                    width: "100%",
                    maxWidth: "800px",
                    height: "300px",
                    borderRadius: "8px",
                    overflow: "hidden",
                    boxShadow: "0 4px 12px rgba(0,0,0,0.15)",
                  }}
                  dangerouslySetInnerHTML={{
                    __html: service?.service?.centre?.googleMapLink,
                  }}
                ></div>
                {/* Review Form for small screens */}
                <div className="review-section d-block d-lg-none">
                  <div className="review-card">
                    <h5 className="review-title">Write a Review</h5>

                    <form onSubmit={handleReviewSubmit}>
                      {/* Rating */}
                      <div className="review-group">
                        <label>
                          Rating <span>(Optional)</span>
                        </label>

                        <div className="review-stars">
                          {[1, 2, 3, 4, 5].map((star) => (
                            <span
                              key={star}
                              className={`review-star ${
                                star <= reviewData.rating ? "filled" : ""
                              }`}
                              onClick={() => handleRatingClick(star)}
                            >
                              ★
                            </span>
                          ))}
                        </div>

                        <small>Click to rate (1–5 stars) – Optional</small>
                      </div>

                      {/* Review Text */}
                      <div className="review-group">
                        <label>Your Review</label>

                        <textarea
                          placeholder="Share your experience with this service..."
                          value={reviewData.review}
                          onChange={(e) =>
                            setReviewData((prev) => ({
                              ...prev,
                              review: e.target.value,
                            }))
                          }
                          rows="4"
                          maxLength="1000"
                        />

                        <small>
                          {reviewData.review.length}/1000 characters
                        </small>
                      </div>

                      <button
                        type="submit"
                        className="review-submit"
                        disabled={
                          submitting ||
                          (!reviewData.rating && !reviewData.review.trim())
                        }
                      >
                        {submitting ? "Submitting..." : "Submit Review"}
                      </button>
                    </form>
                  </div>
                </div>
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Login Modal for Reviews */}
      <UnifiedAuthModal 
        isOpen={showLoginModal}
        onClose={() => setShowLoginModal(false)}
        restrictToRole="patient"
        shouldRedirect={false}
        onSuccess={() => {
          setShowLoginModal(false);
          // Review will be handled by the useEffect that checks for pendingReview on mount/login
          window.location.reload(); // Simplest way to re-trigger the check and update UI
        }}
      />

      {/* Doctor Details Modal */}
      {showDoctorModal && selectedDoctor && (
        <div
          onClick={closeDoctorModal}
          style={{
            position: "fixed",
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            backgroundColor: "rgba(15, 23, 42, 0.6)",
            backdropFilter: "blur(4px)",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            zIndex: 1000,
            padding: "20px",
          }}
        >
          <div
            onClick={(e) => e.stopPropagation()}
            style={{
              backgroundColor: "#fff",
              borderRadius: "20px",
              maxWidth: "850px",
              width: "100%",
              maxHeight: "90vh",
              boxShadow: "0 25px 50px -12px rgba(0, 0, 0, 0.25)",
              position: "relative",
              overflow: "hidden",
              display: "flex",
              flexDirection: "column",
            }}
          >
            {/* Header */}
            <div
              style={{
                background: "linear-gradient(135deg, #1e293b 0%, #334155 100%)",
                color: "#fff",
                padding: "12px 20px",
                fontSize: "18px",
                fontWeight: "700",
                display: "flex",
                alignItems: "center",
                justifyContent: "space-between",
                borderBottom: "1px solid rgba(255,255,255,0.1)",
              }}
            >
              <div style={{ display: "flex", alignItems: "center", gap: "10px" }}>
                <div style={{ background: "rgba(255,255,255,0.1)", padding: "6px", borderRadius: "8px" }}>
                  <FaUserMd size={20} />
                </div>
                <span>Doctor Profile</span>
              </div>
              <button
                onClick={closeDoctorModal}
                style={{
                  background: "rgba(255,255,255,0.1)",
                  border: "none",
                  width: "32px",
                  height: "32px",
                  borderRadius: "8px",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  color: "#fff",
                  cursor: "pointer",
                  transition: "background 0.2s",
                }}
                onMouseOver={(e) => e.currentTarget.style.background = "rgba(255,255,255,0.2)"}
                onMouseOut={(e) => e.currentTarget.style.background = "rgba(255,255,255,0.1)"}
              >
                &times;
              </button>
            </div>

            {/* Body */}
            <div
              style={{
                padding: "24px 20px",
                overflowY: "auto",
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                color: "#1e293b",
                textAlign: "center",
              }}
            >
              {/* Profile Photo - Badge Style */}
              <div style={{ 
                position: "relative", 
                marginBottom: "16px",
                padding: "6px",
                background: "#f8fafc",
                borderRadius: "50%",
                boxShadow: "0 8px 20px -5px rgba(0,0,0,0.1)",
                border: "1px solid #e2e8f0"
              }}>
                <img
                  src={selectedDoctor.profilePhoto}
                  alt={selectedDoctor.name}
                  style={{
                    width: "100px",
                    height: "100px",
                    objectFit: "cover",
                    borderRadius: "50%",
                    display: "block"
                  }}
                />
              </div>

              {/* Identity Section */}
              <div style={{ marginBottom: "20px", width: "100%" }}>
                <h2 style={{ 
                  fontSize: "22px", 
                  fontWeight: "800", 
                  marginBottom: "2px",
                  color: "#0f172a" 
                }}>
                  {selectedDoctor.name}
                </h2>
                <div style={{ 
                  fontSize: "13px", 
                  fontWeight: "700", 
                  color: "#3b82f6", 
                  textTransform: "uppercase", 
                  letterSpacing: "1.2px" 
                }}>
                  {selectedDoctor.specialization || "Medical Professional"}
                </div>
                <div style={{ 
                  width: "40px", 
                  height: "2px", 
                  background: "#e2e8f0", 
                  borderRadius: "2px", 
                  margin: "12px auto" 
                }}></div>
              </div>

              {/* Details List */}
              <div style={{ 
                width: "100%", 
                maxWidth: "600px",
                display: "grid", 
                gridTemplateColumns: "repeat(auto-fit, minmax(200px, 1fr))", 
                gap: "12px",
                textAlign: "left",
                marginBottom: "20px"
              }}>
                {/* Qualification */}
                {selectedDoctor.qualification && (
                  <div style={{ 
                    display: "flex", 
                    gap: "12px", 
                    padding: "12px", 
                    background: "#f8fafc", 
                    borderRadius: "12px",
                    border: "1px solid #f1f5f9"
                  }}>
                    <div style={{ color: "#3b82f6" }}><FaGraduationCap size={18} /></div>
                    <div>
                      <div style={{ fontSize: "11px", fontWeight: "700", color: "#94a3b8", textTransform: "uppercase" }}>Qualification</div>
                      <div style={{ fontSize: "14px", color: "#1e293b", fontWeight: "600" }}>{selectedDoctor.qualification}</div>
                    </div>
                  </div>
                )}

                {/* Experience */}
                {selectedDoctor.experience && (
                  <div style={{ 
                    display: "flex", 
                    gap: "12px", 
                    padding: "12px", 
                    background: "#f8fafc", 
                    borderRadius: "12px",
                    border: "1px solid #f1f5f9"
                  }}>
                    <div style={{ color: "#3b82f6" }}><FaCalendarAlt size={18} /></div>
                    <div>
                      <div style={{ fontSize: "11px", fontWeight: "700", color: "#94a3b8", textTransform: "uppercase" }}>Experience</div>
                      <div style={{ fontSize: "14px", color: "#1e293b", fontWeight: "600" }}>{selectedDoctor.experience}</div>
                    </div>
                  </div>
                )}
              </div>

              {/* About Section */}
              {selectedDoctor.aboutDoctor && (
                <div style={{ 
                  width: "100%",
                  maxWidth: "700px",
                  padding: "16px", 
                  background: "#ffffff", 
                  borderRadius: "16px",
                  border: "1px solid #e2e8f0",
                  textAlign: "left"
                }}>
                  <div style={{ display: "flex", alignItems: "center", gap: "8px", marginBottom: "8px" }}>
                    <FaInfoCircle size={14} style={{ color: "#3b82f6" }} />
                    <span style={{ fontSize: "11px", fontWeight: "700", color: "#94a3b8", textTransform: "uppercase" }}>About the Doctor</span>
                  </div>
                  <p style={{ 
                    fontSize: "14px", 
                    lineHeight: "1.5", 
                    color: "#475569", 
                    margin: 0,
                    whiteSpace: "pre-line"
                  }}>
                    {selectedDoctor.aboutDoctor}
                  </p>
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
    </>
  );
};

export default ProductDetails;